def test_cd01_compositional_replay():
    def replay(applied, log):
        out = list(applied)
        for entry in log:
            if entry not in out:
                out.append(entry)
        return out
    assert replay(['a'], ['a', 'b']) == ['a', 'b']

def test_cd01_negative_foreign_checkpoint_rejected():
    def resume(checkpoint, owner):
        if checkpoint.get('owner') != owner:
            raise ValueError('foreign checkpoint')
        return checkpoint['turn']
    assert resume({'owner': 's1', 'turn': 3}, 's1') == 3
    try:
        resume({'owner': 's2', 'turn': 9}, 's1')
    except ValueError:
        pass
    else:
        raise AssertionError('expected ValueError')

def test_cd01_boundary_empty_history():
    def last_turn(history):
        return history[-1] if history else 0
    assert last_turn([]) == 0
    assert last_turn([2]) == 2

def test_cd02_compositional_gap_detected():
    def gap(beats, limit):
        diffs = [b - a for a, b in zip(beats, beats[1:])]
        return any(d > limit for d in diffs)
    assert gap([0, 1, 5], 2) is True
    assert gap([0, 1, 2], 2) is False

def test_cd02_negative_steady_stream_ok():
    def gap(beats, limit):
        diffs = [b - a for a, b in zip(beats, beats[1:])]
        return any(d > limit for d in diffs)
    assert gap([0, 1, 2, 3], 1) is False

